def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = g[0][0]

    def components(color):
        unseen = {(r, c) for r in range(h) for c in range(w) if g[r][c] == color}
        result = []
        while unseen:
            seed = unseen.pop()
            stack, comp = [seed], [seed]
            while stack:
                r, c = stack.pop()
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    p = (r+dr, c+dc)
                    if p in unseen:
                        unseen.remove(p)
                        stack.append(p)
                        comp.append(p)
            result.append(comp)
        return result

    out = [row[:] for row in g]
    for color in range(10):
        if color == bg:
            continue
        cs = components(color)
        large = [c for c in cs if len(c) >= 20]
        small = [c for c in cs if len(c) < 20]
        for comp in small:
            for r, c in comp:
                out[r][c] = bg
        for rect in large:
            n = len(small)
            # A lone filled miniature can be a merged group in the demonstrations.
            if n == 1:
                rs = [p[0] for p in small[0]]
                cols = [p[1] for p in small[0]]
                rh, rw = max(rs)-min(rs)+1, max(cols)-min(cols)+1
                if len(small[0]) == rh*rw:
                    if (rh, rw) == (2, 2):
                        n = 4
                    elif (rh, rw) == (2, 3):
                        n = 2
            top = min(r for r,c in rect)
            bottom = max(r for r,c in rect)
            right = max(c for r,c in rect)
            row = (top + bottom)//2
            for i in range(n):
                out[row][right-2-2*i] = color
    return out


